<script setup>
import{ref,onMounted}from'vue';import{api,json}from'../api';import{Plus,Pencil,Power,Trash2}from'lucide-vue-next';import Modal from'../components/Modal.vue';import Toast from'../components/Toast.vue'
const rows=ref([]),cats=ref([]),dishes=ref([]),show=ref(false),form=ref({}),toast=ref('');async function load(){rows.value=await api('/api/admin/setmeal/page')}async function refs(){cats.value=(await api('/api/admin/category/page?type=2')).filter(x=>x.status===1);dishes.value=(await api('/api/admin/dish/page?status=1'))}async function edit(r={price:0,status:1,dishes:[]}){form.value={...r,dishes:[]};if(r.id)form.value.dishes=await api(`/api/admin/setmeal/${r.id}/dishes`);show.value=true}function toggleDish(id){const i=form.value.dishes.findIndex(x=>x.dishId===id);i>=0?form.value.dishes.splice(i,1):form.value.dishes.push({dishId:id,copies:1})}async function save(){await api('/api/admin/setmeal',{method:form.value.id?'PUT':'POST',body:json(form.value)});show.value=false;toast.value='Saved';setTimeout(()=>toast.value='',2200);load()}async function status(r){await api(`/api/admin/setmeal/${r.id}/status/${r.status?0:1}`,{method:'PATCH'});load()}async function remove(r){if(!confirm(`Delete set meal "${r.name}"?`))return;await api(`/api/admin/setmeal/${r.id}`,{method:'DELETE'});load()}onMounted(()=>{load();refs()})
</script>
<template><div class="page-head"><div><h1>Set Meals</h1><p>Combine dishes and set the set meal price</p></div><button class="primary" @click="edit()"><Plus :size="18"/>Add Set Meal</button></div><div class="table-wrap"><table><thead><tr><th>Set Meal Name</th><th>Category</th><th>Price</th><th>Status</th><th class="actions">Actions</th></tr></thead><tbody><tr v-for="r in rows"><td><strong>{{r.name}}</strong><small>{{r.description||'No description'}}</small></td><td>{{cats.find(c=>c.id===r.categoryId)?.name||r.categoryId}}</td><td class="price">¥ {{r.price}}</td><td><span class="status" :class="r.status?'on':'off'">{{r.status?'On sale':'Disabled'}}</span></td><td class="actions"><button title="Edit" @click="edit(r)"><Pencil/></button><button title="Toggle status" @click="status(r)"><Power/></button><button title="Delete" class="danger" @click="remove(r)"><Trash2/></button></td></tr></tbody></table></div><Modal v-if="show" :title="form.id?'Edit Set Meal':'Add Set Meal'" @close="show=false"><form class="form-grid" @submit.prevent="save"><label>Set Meal Name<input v-model="form.name" required/></label><label>Set Meal Category<select v-model.number="form.categoryId" required><option v-for="c in cats" :value="c.id">{{c.name}}</option></select></label><label>Set Meal Price<input v-model.number="form.price" type="number" min="0.01" step="0.01" required/></label><label class="full">Set Meal Description<textarea v-model="form.description" rows="2"/></label><fieldset class="full"><legend>Select Dishes</legend><div class="dish-picks"><label v-for="d in dishes"><input type="checkbox" :checked="form.dishes.some(x=>x.dishId===d.id)" @change="toggleDish(d.id)"/><span>{{d.name}} · ¥{{d.price}}</span></label></div></fieldset><footer><button type="button" class="secondary" @click="show=false">Cancel</button><button class="primary">Save</button></footer></form></Modal><Toast :message="toast"/></template>
